 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const root = new Group();
  root.name = 'quote-panel-pricing';

  const tweens = [];

  // ---- backdrop stage gradient ----
  const backdropGeo = new PlaneGeometry(8, 7);
  const gradNode = mix(color('#0b0b10'), color('#16161d'), uv().y);
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: gradNode });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.name = 'backdrop';
  root.add(backdrop);

  // ---- card group ----
  const cardGroup = new Group();
  cardGroup.name = 'card-group';
  root.add(cardGroup);

  // atlas source is 512 x 320 -> aspect 1.6
  const cardW = 3.2;
  const cardH = 2.0;

  // accent edge frame
  const edgeGeo = new PlaneGeometry(cardW + 0.06, cardH + 0.06);
  const edgeMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.name = 'accent-edge';
  edge.position.z = -0.01;
  cardGroup.add(edge);

  // textured plane
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });
  const card = new Mesh(cardGeo, cardMat);
  card.name = 'quote-card';
  cardGroup.add(card);

  // load texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  }).catch(() => {
    // fall back to neutral surface tone
    cardMat.colorNode = color('#16161d');
  });

  // ---- motion helpers ----
  const liftCard = (y, duration = 0.35, ease = 'power2.out') => {
    tweens.forEach((t) => { if (t && t.vars && t.vars.y !== undefined) t.kill(); });
    const t = gsap.to(cardGroup.position, { y, duration, ease });
    tweens.push(t);
    return t;
  };

  const pulseEdge = (active) => {
    const t = gsap.to(edgeMat, {
      opacity: active ? 0.85 : 0,
      duration: 0.25,
      ease: 'power2.out',
    });
    tweens.push(t);
    return t;
  };

  // ---- cinematic primitive: parallax-scroll ----
  const parallax = ctx.primitives['parallax-scroll'](root, {
    intensity: 0.25,
    trigger: 'scroll',
  });

  // ---- event handlers ----
  root.userData.handlers = {
    hoverEnter: () => {
      pulseEdge(true);
      liftCard(0.15, 0.4, 'power2.out');
    },
    hoverLeave: () => {
      pulseEdge(false);
      liftCard(0, 0.45, 'power3.out');
    },
    focus: (active) => {
      pulseEdge(active);
    },
    click: () => {
      const press = gsap.timeline();
      press.to(cardGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      press.to(cardGroup.scale, { x: 1, y: 1, duration: 0.25, ease: 'power2.out' });
      tweens.push(press);
      ctx.emit('hub-pricing.select', { nodeId: config.id, hub: 'hub-pricing' });
    },
  };

  // expose data binding metadata
  root.userData.dataBindings = config.dataBindings || [];

  // ---- cleanup ----
  root.userData.cleanup = () => {
    if (parallax && typeof parallax.cleanup === 'function') parallax.cleanup();
    tweens.forEach((t) => t && t.kill && t.kill());
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const m = obj.material;
        if (m.map) { m.map.dispose(); m.map = null; }
        if (m.colorNode && typeof m.colorNode.dispose === 'function') m.colorNode.dispose();
        m.dispose();
      }
    });
  };

  return root;
}
